{
  "items": [
    {
      "name": "MvPolynomial.degreeOf",
      "module_name": "Mathlib.Algebra.MvPolynomial.Degrees",
      "kind": "definition",
      "type": "{R : Type u} → {σ : Type u_1} → [inst : CommSemiring R] → σ → MvPolynomial σ R → ℕ"
    },
    {
      "name": "MvPolynomial.degreeOf_mul_X_self",
      "module_name": "Mathlib.Algebra.MvPolynomial.Degrees",
      "kind": "theorem",
      "type": "∀ {R : Type u} {σ : Type u_1} [inst : CommSemiring R] (j : σ) (f : MvPolynomial σ R),\n  MvPolynomial.degreeOf j (f * MvPolynomial.X j) ≤ MvPolynomial.degreeOf j f + 1"
    },
    {
      "name": "MvPolynomial.totalDegree_rename_le",
      "module_name": "Mathlib.Algebra.MvPolynomial.Degrees",
      "kind": "theorem",
      "type": "∀ {R : Type u} {σ : Type u_1} {τ : Type u_2} [inst : CommSemiring R] (f : σ → τ) (p : MvPolynomial σ R),\n  ((MvPolynomial.rename f) p).totalDegree ≤ p.totalDegree"
    },
    {
      "name": "MvPolynomial.degreeOf_pow_le",
      "module_name": "Mathlib.Algebra.MvPolynomial.Degrees",
      "kind": "theorem",
      "type": "∀ {R : Type u} {σ : Type u_1} [inst : CommSemiring R] (i : σ) (p : MvPolynomial σ R) (n : ℕ),\n  MvPolynomial.degreeOf i (p ^ n) ≤ n * MvPolynomial.degreeOf i p"
    },
    {
      "name": "MvPolynomial.degreeOf_C_mul_le",
      "module_name": "Mathlib.Algebra.MvPolynomial.Degrees",
      "kind": "theorem",
      "type": "∀ {R : Type u} {σ : Type u_1} [inst : CommSemiring R] (p : MvPolynomial σ R) (i : σ) (c : R),\n  MvPolynomial.degreeOf i (MvPolynomial.C c * p) ≤ MvPolynomial.degreeOf i p"
    },
    {
      "name": "MvPolynomial.degreeOf_mul_C_le",
      "module_name": "Mathlib.Algebra.MvPolynomial.Degrees",
      "kind": "theorem",
      "type": "∀ {R : Type u} {σ : Type u_1} [inst : CommSemiring R] (p : MvPolynomial σ R) (i : σ) (c : R),\n  MvPolynomial.degreeOf i (p * MvPolynomial.C c) ≤ MvPolynomial.degreeOf i p"
    },
    {
      "name": "MvPolynomial.degrees_map_of_injective",
      "module_name": "Mathlib.Algebra.MvPolynomial.Degrees",
      "kind": "theorem",
      "type": "∀ {R : Type u} {S : Type v} {σ : Type u_1} [inst : CommSemiring R] [inst_1 : CommSemiring S] (p : MvPolynomial σ R)\n  {f : R →+* S}, Function.Injective ⇑f → ((MvPolynomial.map f) p).degrees = p.degrees"
    },
    {
      "name": "MvPolynomial.degreeOf_rename_of_injective",
      "module_name": "Mathlib.Algebra.MvPolynomial.Degrees",
      "kind": "theorem",
      "type": "∀ {R : Type u} {σ : Type u_1} {τ : Type u_2} [inst : CommSemiring R] {p : MvPolynomial σ R} {f : σ → τ},\n  Function.Injective f → ∀ (i : σ), MvPolynomial.degreeOf (f i) ((MvPolynomial.rename f) p) = MvPolynomial.degreeOf i p"
    }
  ]
}

{
  "items": [
    {
      "name": "MvPolynomial.IsHomogeneous.rename_isHomogeneous",
      "module_name": "Mathlib.RingTheory.MvPolynomial.Homogeneous",
      "kind": "theorem",
      "type": "∀ {σ : Type u_1} {τ : Type u_2} {R : Type u_3} [inst : CommSemiring R] {φ : MvPolynomial σ R} {n : ℕ} {f : σ → τ},\n  φ.IsHomogeneous n → ((MvPolynomial.rename f) φ).IsHomogeneous n"
    },
    {
      "name": "Polynomial.algEquivAevalXAddC",
      "module_name": "Mathlib.Algebra.Polynomial.AlgebraMap",
      "kind": "definition",
      "type": "{R : Type u_3} → [inst : CommRing R] → R → Polynomial R ≃ₐ[R] Polynomial R"
    },
    {
      "name": "MvPolynomial.homogeneousComponent",
      "module_name": "Mathlib.RingTheory.MvPolynomial.Homogeneous",
      "kind": "definition",
      "type": "{σ : Type u_1} → {R : Type u_3} → [inst : CommSemiring R] → ℕ → MvPolynomial σ R →ₗ[R] MvPolynomial σ R"
    },
    {
      "name": "MvPolynomial.IsHomogeneous.rename_isHomogeneous_iff",
      "module_name": "Mathlib.RingTheory.MvPolynomial.Homogeneous",
      "kind": "theorem",
      "type": "∀ {σ : Type u_1} {τ : Type u_2} {R : Type u_3} [inst : CommSemiring R] {φ : MvPolynomial σ R} {n : ℕ} {f : σ → τ},\n  Function.Injective f → (((MvPolynomial.rename f) φ).IsHomogeneous n ↔ φ.IsHomogeneous n)"
    },
    {
      "name": "MvPolynomial.degreeOf_mul_X_of_ne",
      "module_name": "Mathlib.Algebra.MvPolynomial.Degrees",
      "kind": "theorem",
      "type": "∀ {R : Type u} {σ : Type u_1} [inst : CommSemiring R] {i j : σ} (f : MvPolynomial σ R),\n  i ≠ j → MvPolynomial.degreeOf i (f * MvPolynomial.X j) = MvPolynomial.degreeOf i f"
    },
    {
      "name": "MvPolynomial.IsHomogeneous.map",
      "module_name": "Mathlib.RingTheory.MvPolynomial.Homogeneous",
      "kind": "theorem",
      "type": "∀ {σ : Type u_1} {R : Type u_3} {S : Type u_4} [inst : CommSemiring R] [inst_1 : CommSemiring S] {φ : MvPolynomial σ R}\n  {n : ℕ}, φ.IsHomogeneous n → ∀ (f : R →+* S), ((MvPolynomial.map f) φ).IsHomogeneous n"
    },
    {
      "name": "MvPolynomial.degreeOf_neg",
      "module_name": "Mathlib.Algebra.MvPolynomial.CommRing",
      "kind": "theorem",
      "type": "∀ {R : Type u} {σ : Type u_1} [inst : CommRing R] (i : σ) (p : MvPolynomial σ R),\n  MvPolynomial.degreeOf i (-p) = MvPolynomial.degreeOf i p"
    },
    {
      "name": "MvPolynomial.degreeOf_rename_of_injective",
      "module_name": "Mathlib.Algebra.MvPolynomial.Degrees",
      "kind": "theorem",
      "type": "∀ {R : Type u} {σ : Type u_1} {τ : Type u_2} [inst : CommSemiring R] {p : MvPolynomial σ R} {f : σ → τ},\n  Function.Injective f → ∀ (i : σ), MvPolynomial.degreeOf (f i) ((MvPolynomial.rename f) p) = MvPolynomial.degreeOf i p"
    }
  ]
}

{
  "items": [
    {
      "name": "MvPolynomial.aeval_natDegree_le",
      "module_name": "Mathlib.RingTheory.Polynomial.Basic",
      "kind": "theorem",
      "type": "∀ {σ : Type v} {R : Type u_2} [inst : CommSemiring R] {m n : ℕ} (F : MvPolynomial σ R),\n  F.totalDegree ≤ m →\n    ∀ (f : σ → Polynomial R), (∀ (i : σ), (f i).natDegree ≤ n) → ((MvPolynomial.aeval f) F).natDegree ≤ m * n"
    },
    {
      "name": "Polynomial.degree_mul_le",
      "module_name": "Mathlib.Algebra.Polynomial.Degree.Definitions",
      "kind": "theorem",
      "type": "∀ {R : Type u} [inst : Semiring R] (p q : Polynomial R), (p * q).degree ≤ p.degree + q.degree"
    },
    {
      "name": "Polynomial.natDegree_list_prod_le",
      "module_name": "Mathlib.Algebra.Polynomial.BigOperators",
      "kind": "theorem",
      "type": "∀ {S : Type u_1} [inst : Semiring S] (l : List (Polynomial S)), l.prod.natDegree ≤ (List.map Polynomial.natDegree l).sum"
    },
    {
      "name": "Polynomial.degree_prod_le",
      "module_name": "Mathlib.Algebra.Polynomial.BigOperators",
      "kind": "theorem",
      "type": "∀ {R : Type u} {ι : Type w} (s : Finset ι) [inst : CommSemiring R] (f : ι → Polynomial R),\n  (∏ i ∈ s, f i).degree ≤ ∑ i ∈ s, (f i).degree"
    },
    {
      "name": "Polynomial.degree_mul",
      "module_name": "Mathlib.Algebra.Polynomial.Degree.Operations",
      "kind": "theorem",
      "type": "∀ {R : Type u} [inst : Semiring R] [NoZeroDivisors R] {p q : Polynomial R}, (p * q).degree = p.degree + q.degree"
    },
    {
      "name": "Polynomial.natDegree_sum_le_of_forall_le",
      "module_name": "Mathlib.Algebra.Polynomial.BigOperators",
      "kind": "theorem",
      "type": "∀ {ι : Type w} (s : Finset ι) {S : Type u_1} [inst : Semiring S] {n : ℕ} (f : ι → Polynomial S),\n  (∀ i ∈ s, (f i).natDegree ≤ n) → (∑ i ∈ s, f i).natDegree ≤ n"
    },
    {
      "name": "Polynomial.degree_prod",
      "module_name": "Mathlib.Algebra.Polynomial.BigOperators",
      "kind": "theorem",
      "type": "∀ {R : Type u} {ι : Type w} (s : Finset ι) [inst : CommSemiring R] [NoZeroDivisors R] (f : ι → Polynomial R)\n  [Nontrivial R], (∏ i ∈ s, f i).degree = ∑ i ∈ s, (f i).degree"
    },
    {
      "name": "Polynomial.degree_mul_le_of_le",
      "module_name": "Mathlib.Algebra.Polynomial.Degree.Definitions",
      "kind": "theorem",
      "type": "∀ {R : Type u} [inst : Semiring R] {p q : Polynomial R} {a b : WithBot ℕ},\n  p.degree ≤ a → q.degree ≤ b → (p * q).degree ≤ a + b"
    }
  ]
}

